scripts.script:
if (Macros.checkStance(actor, args) && args.attacker) {
    const effectData = {
        name: "笨拙",
        icon: "icons/svg/anchor.svg",
        changes: [{ key: "system.combat.dodge", mode: 2, value: "-5" }],
        flags: { "xjzl-system": { slug: "benzhuo", stackable: true, maxStacks: 0 } }
    };
    await game.xjzl.api.effects.addEffect(args.attacker, effectData);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    await game.xjzl.api.effects.addEffect(args.target, "bleed_stack");
    ui.notifications.info(`${args.target.name} 被施加了流血`);
}

const hasBleed = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "bleed_stack");
if (hasBleed) {
    args.config.amount += 10;
    ui.notifications.info("流血加成 +10");
}

const myHit = args.attacker.system.combat.hitWaigongTotal;
const targetDodge = args.target.system.combat.dodgeTotal ?? 10;

if (targetDodge < myHit) {
    // 基础-1，每升级一次再-1。即 Lv1=-1, Lv2=-2, Lv3=-3
    const lvl = Math.max(1, args.move.computedLevel || 1);
    args.flags.critThresholdMod += lvl;

    const content = `<div class="xjzl-chat-card" style="padding: 10px;">
        <div style="font-weight:bold; color:#d35400; border-bottom:1px solid #ccc; margin-bottom:5px;">
            <i class="fas fa-bullseye"></i> 势如破竹 - 压制生效
        </div>
        <div style="font-size: 0.9em; color: #444;">
            目标 <b>${args.target.name}</b> 闪避低于命中，暴击阈值降低 <b>${lvl}</b> 点。
        </div>
    </div>`;
    ChatMessage.create({ user: game.user.id, speaker: ChatMessage.getSpeaker({ actor: args.attacker }), content: content });
}

if (args.isHit) {
    // 读取面板伤害作为 amount
    const damageResult = await args.target.applyDamage({
        amount: args.baseDamage,
        type: args.damageType,
        attacker: args.attacker,
        isHit: true,
        isCrit: args.isCrit,
        isBroken: args.isBroken,
        element: args.element,
        source: "move"
    });

    // 构建战报文本
    const hpLost = damageResult.hpLost || 0;
    const hutiLost = damageResult.hutiLost || 0;
    const mpLost = damageResult.mpLost || 0;

    const info = [];
    if(hpLost > 0) info.push(`HP -${hpLost}`);
    if(hutiLost > 0) info.push(`护体 -${hutiLost}`);
    if(mpLost > 0) info.push(`内力 -${mpLost}`);
    const resultStr = info.length > 0 ? info.join(", ") : "被防御或抗性抵消";

    const content = `<div class="xjzl-chat-card" style="padding: 10px;">
        <div style="border-left: 4px solid #2e7d32; padding-left: 8px; margin-bottom: 5px;">
            <h4 style="margin:0; color:#2e7d32;">第二道绿芒</h4>
        </div>
        <div style="font-size: 0.9em;">
            <p>再次命中 <b>${args.target.name}</b>！</p>
            <div style="background:rgba(0,0,0,0.05); padding:5px; border-radius:4px; font-weight:bold; color:#8b0000;">
                ${resultStr}
            </div>
        </div>
    </div>`;

    ChatMessage.create({ user: game.user.id, speaker: ChatMessage.getSpeaker({ actor: args.attacker }), content: content });
}

// 检测身上是否有随行buff (通过 slug 判断更稳健)
if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "suixing")) {
    args.output.damage += 5;
    args.output.bonusDesc.push("随行加成 +5");
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    // 构造包含系统预设状态 ID 和 持续回合 的数据对象
    const effectData = { id: "root", duration: { rounds: 1 } };
    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ui.notifications.info(`${args.target.name} 被禁足`);
}

const lvl = Math.max(1, move.computedLevel || 1);

// 规则：随行速度+1... 升级：随行速度+1。即 Lv1=+1, Lv2=+2
const val = lvl;

// 1. 获取模板
const eff = thisItem.effects.getName("随行").toObject();

// 2. 修改动态数值
// 修改速度 (Change 索引 0)
eff.changes[0].value = String(val);

// 将等级存入 Flag，供随行自身的脚本读取以计算暴击
eff.flags["xjzl-system"].level = val;

// 设置持续时间
eff.duration = { rounds: 1 };

// 3. 应用
await game.xjzl.api.effects.addEffect(actor, eff);

if (actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "suixing")) {
    args.output.damage += 10;
    args.output.bonusDesc.push("随行加成 +10");
}

// 检查是否在使用盘蛇刺招式
if (item && item.name.includes("盘蛇刺")) {
    // 读取施加时存入的等级
    const bonus = thisEffect.getFlag("xjzl-system", "level") || 1;
    // 增加暴击修正 (正数=更容易暴击)
    args.flags.critThresholdMod += bonus;
}

if (args.isHit && args.isBroken) {
    const effectData = {
        name: "乏力",
        icon: "icons/svg/downgrade.svg",
        changes: [{ key: "system.combat.damages.skill.mod", mode: 2, value: "-10" }],
        flags: { "xjzl-system": { slug: "fali", stackable: true, maxStacks: 3 } }
    };
    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ui.notifications.info(`${args.target.name} 乏力层数+1`);
}

if (args.isBroken) {
    const eff = thisItem.effects.getName("五毒").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, eff);
    ui.notifications.info(`${args.target.name} 中了五毒`);
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    const root = CONFIG.statusEffects.find(e => e.id === "root");
    const eff = foundry.utils.deepClone(root);
    eff.duration = { rounds: 1 };
    await game.xjzl.api.effects.addEffect(args.target, eff);
    ui.notifications.info(`${args.target.name} 被禁足`);
}

// 1. 筛选条件：必须是离魂镖套路，且必须命中
if (!item || !item.name.includes("离魂镖")) return;
if (!args.isHit) return;

// 2. 读取施法时存入的固定伤害加成 (由绝招等级决定)
const flatBonus = thisEffect.getFlag("xjzl-system", "flatBonus") || 0;

// 3. 计算伤害: 0.4 内息 + 固定加成
const neixi = actor.system.stats.neixi.total;
const dmg = Math.floor(neixi * 0.4) + flatBonus;

if (dmg > 0) {
    // 4. 应用毒素伤害 (无视防御)
    await args.target.applyDamage({
        amount: dmg,
        type: "poison",
        attacker: actor,
        isHit: true,
        ignoreDefense: true
    });

    // 5. 发送卡片 (带边距样式)
    const cardContent = `
        <div class="xjzl-chat-card">
            <div style="padding:5px; padding-left: 8px; border-left: 4px solid #800080; background: rgba(128, 0, 128, 0.1); margin-left: 2px;">
                <div style="font-weight:bold; color:#800080; font-size:1.1em;">
                    <i class="fas fa-skull-crossbones"></i> 神魂颠倒
                </div>
                <div style="font-size:0.9em; margin-top:5px; color:#555;">
                    经脉逆行，毒气攻心！<br>
                    附加毒伤: <span style="font-weight:bold; color:purple;">${dmg}</span>
                </div>
            </div>
        </div>`;

    ChatMessage.create({
        content: cardContent,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

// 1. 校验架招触发条件
if (!Macros.checkStance(actor, args)) return;

// 2. 获取架招等级 (从 Item 数据中查找当前招式)
const stanceMove = thisItem.system.moves.find(m => m.id === actor.system.martial.stance);
const lvl = Math.max(1, stanceMove?.computedLevel || 1);

// 3. 计算速度加成 (基础3 + 升级成长)
// 升级描述: 游魂速度+1。 Level 1 -> +3, Level 2 -> +4
const speedBonus = 3 + (lvl - 1);

// 4. 构建特效数据
const effectData = {
    name: "游魂",
    icon: "systems/xjzl-system/assets/icons/wuxue/唐门.png",
    duration: { rounds: 3 },
    flags: {
        "xjzl-system": {
            slug: "youhun",
            stackable: false
        }
    },
    changes: [
        // 速度加成
        { key: "system.combat.speed", mode: 2, value: speedBonus }
    ]
};

await game.xjzl.api.effects.addEffect(actor, effectData);

if (args.isHit && args.isBroken) {
    const lvl = Math.max(1, move.computedLevel || 1);
    const rounds = 1 + (lvl - 1);

    // 使用系统预设 ID "cuoluan"
    const effectData = {
        id: "cuoluan",
        icon: "systems/xjzl-system/assets/icons/wuxue/唐门.png",
        duration: { rounds: rounds }
    };

    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ui.notifications.info(`${args.target.name} 陷入错乱！`);
}

const lvl = Math.max(1, move.computedLevel || 1);
const rounds = 1 + (lvl - 1);
// 计算升级带来的额外固定伤害: (Level - 1) * 20
const extraFlatDmg = (lvl - 1) * 20;

// 获取模板
const effectData = thisItem.effects.getName("神魂颠倒").toObject();
delete effectData._id;
effectData.origin = thisItem.uuid;
effectData.duration = { rounds: rounds };

// 将计算好的固定伤害存入 Flag，供特效脚本读取
foundry.utils.setProperty(effectData, "flags.xjzl-system.flatBonus", extraFlatDmg);

// 应用
await game.xjzl.api.effects.addEffect(args.attacker, effectData);

// 标记自动应用，隐藏卡片按钮
args.flags.autoApplied = true;

if (args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "deaf" || e.name === "耳鸣")) {
    args.config.amount += 20;
    actor.showFloatyText("悲痛无声: 耳鸣加伤", { fill: "#00FF00" });
}

if (!Macros.checkStance(actor, args)) return;

// 获取当前架招数据以计算等级
const stanceId = actor.system.martial.stance;
const stanceMove = thisItem.system.moves.find(m => m.id === stanceId);
const level = Math.max(1, stanceMove?.computedLevel || 1);
const rounds = 1 + (level - 1);

const effectData = thisItem.effects.getName("泣血").toObject();
delete effectData._id;
effectData.origin = thisItem.uuid;
effectData.duration = { rounds: rounds };

await game.xjzl.api.effects.addEffect(actor, effectData);

if (args.isHit) {
    const level = Math.max(1, args.move.computedLevel || 1);
    const rounds = 1 + (level - 1);
    // 使用系统预设 ID "deaf"
    const deaf = CONFIG.statusEffects.find(e => e.id === "deaf");
    const effectData = foundry.utils.deepClone(deaf);
    effectData.duration = { rounds: rounds };

    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ui.notifications.info("目标被施加耳鸣。请检查周围3米敌人并手动添加。");
}

if (args.isHit) {
    const bleed = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "bleed_stack");
    if (bleed) {
        const stacks = bleed.getFlag("xjzl-system", "stacks") || 1;
        const dmg = stacks * 10;
        await args.target.applyDamage({ amount: dmg, type: "liushi", attacker: actor });
        await game.xjzl.api.effects.addEffect(args.target, "bloodloss");
        ui.notifications.info(`${args.target.name} 流血引爆！流失 ${dmg} 气血并获得失血。`);
    }
}

if (args.move.weaponType === 'hidden' && args.isHit) {
    await game.xjzl.api.effects.addEffect(args.target, "bleed_stack");
    actor.showFloatyText("泣血: 施加流血", { fill: "#8b0000" });
}

if (args.isHit && !args.target.system.martial.stanceActive) {
    await Macros.requestSave({
        target: args.target,
        attacker: actor,
        type: "dingli",
        dc: 20,
        label: "抵抗自闭",
        onFail: { id: "zibi", duration: { rounds: 1 } }
    });
}

const target = game.user.targets.first()?.actor;
if (target && game.combat) {
    const myInit = game.combat.combatants.find(c => c.actorId === actor.id)?.initiative || 0;
    const targetInit = game.combat.combatants.find(c => c.actorId === target.id)?.initiative || 0;
    if (myInit > targetInit) {
        args.flags.feintLevel += 1;
        ui.notifications.info("先攻压制：虚招优势");
    }
}

// 1. 过滤逻辑：必须是 暗器(hidden) 且 非普攻(basic)
if ((args.move.type === "basic" && args.move.id !== 'opportunity-attack')) return;
if (args.move.weaponType !== "hidden") return;

// 2. 查找源武学 (内存查找，零IO)
// 假设书名未改动
const book = actor.items.find(i => i.name === "暗器秘录" && i.type === "wuxue");
if (!book) return;

// 3. 查找招式数据以确认等级
const passiveMove = book.system.moves.find(m => m.name === "暗器秘录");
// 尚未入门 (计算等级 < 1) 则不生效
if (!passiveMove || (passiveMove.computedLevel || 0) < 1) return;

// 4. 应用数值
args.output.damage += 10;
args.output.bonusDesc.push("暗器秘录 +10");

const lvl = Math.max(1, move.computedLevel || 1);
const dmg = 40 + (lvl - 1) * 10;
const dc = 15;

await Macros.requestSave({
    target: args.target,
    attacker: actor,
    type: 'qinggong',
    dc: dc,
    label: '躲避唐花',
    damageOnFail: { value: dmg, type: 'poison' }
});

const confirm = await foundry.applications.api.DialogV2.confirm({
    window: { title: "暴雨梨花针" },
    content: `<p>是否为<b>偷袭</b>？</p><p style="font-size:0.9em; color:#666;">(偷袭造成双倍伤害)</p>`,
    yes: { label: "是 (双倍)", icon: "fas fa-user-secret" },
    no: { label: "否", icon: "fas fa-times" }
});

if (confirm) {
    args.flags.damageResult.damage *= 2;
    args.flags.damageResult.breakdown += "\n+ 偷袭加成 (x2)";
    ui.notifications.info("偷袭生效！伤害翻倍。");
}

const qg = args.target.system.skills?.qinggong?.total || 0;
const lvl = Math.max(1, move.computedLevel || 1);
const needleDmg = 4 + (lvl - 1) * 1;

// 计算抵消量
const reduction = qg * needleDmg;

if (reduction > 0) {
    args.config.amount = Math.max(0, args.config.amount - reduction);
    if (args.attacker.showFloatyText) {
        args.attacker.showFloatyText(`轻功抵挡 -${reduction}`, { fill: '#cccccc' });
    }
    ChatMessage.create({
        content: `<div class="xjzl-chat-card"><div style="font-size:0.9em; color:#555;">目标利用轻功(${qg}级) 抵消了 <b>${reduction}</b> 点伤害。</div></div>`,
        speaker: ChatMessage.getSpeaker({actor: args.attacker})
    });
}

const lvl = Math.max(1, move.computedLevel || 1);
const dmg = 40 + (lvl - 1) * 10;
const dc = 17 + (lvl - 1) * 2;
const rounds = 1 + (lvl - 1);

// 获取特效模板
const sourceEffect = thisItem.effects.getName('冤魂').toObject();
delete sourceEffect._id;
sourceEffect.duration = { rounds: rounds };
sourceEffect.origin = thisItem.uuid;

await Macros.requestSave({
    target: args.target,
    attacker: actor,
    type: 'qinggong',
    dc: dc,
    label: '躲避阎王帖',
    onFail: sourceEffect,
    damageOnFail: { value: dmg, type: 'poison' }
});

const lvl = Math.max(1, move.computedLevel || 1);
const rounds = 2 + (lvl - 1);

const sourceEffect = thisItem.effects.getName('七步绝命');
if (sourceEffect) {
    const effectData = sourceEffect.toObject();
    delete effectData._id;
    effectData.duration = { rounds: rounds };
    effectData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ui.notifications.info(`已对 ${args.target.name} 施加七步绝命（隐蔽）。`);
}

const lvl = Math.max(1, move.computedLevel || 1);
const dmg = 150 + (lvl - 1) * 50;
const dc = 20 + (lvl - 1) * 3;

// 获取五毒AE模板
const wuduEffect = thisItem.effects.getName('五毒').toObject();
delete wuduEffect._id;
wuduEffect.origin = thisItem.uuid;

await Macros.requestSave({
    target: args.target,
    attacker: actor,
    type: 'qinggong',
    dc: dc,
    label: '躲避满天花雨',
    onFail: wuduEffect,
    damageOnFail: { value: dmg, type: 'poison' }
});

const lvl = Math.max(1, move.computedLevel || 1);
const baseDmg = 50 + (lvl - 1) * 50;
const dotDmg = 5 + (lvl - 1) * 5;

// 1. 应用伤害 (使用脚本触发，支持抗性)
await args.target.applyDamage({
    amount: baseDmg,
    type: 'poison',
    attacker: actor,
    isHit: true,
    ignoreDefense: true // 毒素无视防御
});

// 2. 应用AE
const sourceEffect = thisItem.effects.getName('观音泪');
if (sourceEffect) {
    const effectData = sourceEffect.toObject();
    delete effectData._id;
    effectData.description = `每消耗1点内力，受到${dotDmg}点毒素伤害。`;
    effectData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(args.target, effectData);
    ui.notifications.info(`${args.target.name} 泪如雨下！`);
}
